def simplify_statuses(apps, schema_editor):
    """Assigned becomes In progress; a trade Issue becomes an issue on the whole job."""
    TradeTask = apps.get_model("voids", "TradeTask")
    Void = apps.get_model("voids", "Void")
    JobType = apps.get_model("voids", "JobType")
    TradeTask.objects.filter(status="assigned").update(status="in_progress")
    TradeTask.objects.filter(status="").update(status="stc")
    for task in TradeTask.objects.filter(status="issue").select_related("trade"):
        void = Void.objects.get(pk=task.void_id)
        void.issue_flag = True
        void.issue_note = (f"{void.issue_note}; " if void.issue_note else "") + f"Issue on {task.trade.name}"
        void.save(update_fields=["issue_flag", "issue_note"])
        task.status = "in_progress"
        task.save(update_fields=["status"])
    # Concierge stations are recorded as voids, so that job type is not needed.
    JobType.objects.filter(name="Concierge Station", void__isnull=True).delete()


Migration.operations.append(migrations.RunPython(simplify_statuses, migrations.RunPython.noop))
